package com.weaponsregistration.sales.model;
import com.weaponsregistration.core.model.CoreEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity@Table(name="erp_sale_return")public class SaleReturn extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="sale_id",nullable=false)public InventorySale sale;@ManyToOne(optional=false)@JoinColumn(name="reason_type_id",nullable=false)public SaleReturnReasonType reason;@Column(nullable=false)public boolean cancellation;@Column(nullable=false,length=1000)public String notes;@Column(nullable=false)public LocalDateTime returnedAt;@Column(nullable=false,precision=19,scale=4)public BigDecimal refundAmount;@Column(length=255)public String refundReference;@Column public Long operatorId;@Column public String operatorLogin;@Column(nullable=false,unique=true,length=36)public String requestId;@Column(nullable=false,length=64)public String requestFingerprint;}
